-- =============================================================================
-- Progressive Dungeons — Working MVP migration
-- Branch: progressive-dungeons-working-mvp
-- =============================================================================
-- This migration captures the current production DB state for the PD MVP:
--   * Item 990001 "Warlord's Challenge Horn" (custom click item, no weapon stats)
--   * Spell 42603 "Warlord's Challenge" (silent ON_USE shim, effectid1=254)
--   * Tasks 990201-990217 (one Progressive Dungeon task per dungeon)
--   * task_activities for each task (kill-N enemies, npc_match_list per zone,
--     goalcount already scaled by clamp(round(spawn2_count/8), 20, 100))
--
-- Notes / gotchas observed during development:
--   * `items` has NO `skill` column — weapon skill is derived from `itemtype`.
--     The horn uses itemtype=11 (misc/Misc) with damage=0 / delay=0 so it
--     produces no weapon attack.
--   * `spawn2` has NO `enabled` column.
--   * Client-side display of clicky descriptions requires a matching
--     dbstr_us.txt entry keyed by `spells_new.descnum`. The exported text
--     for descnum 11657 is NOT shipped here (client-side asset).
--
-- Apply order: tables already exist in upstream EQEmu schema; this file only
-- inserts/replaces rows. The INSERTs use `REPLACE INTO` semantics by way of
-- DELETE-then-INSERT to make the migration idempotent.
-- =============================================================================

START TRANSACTION;

-- Remove any prior rows so this migration is replayable.
DELETE FROM task_activities WHERE taskid BETWEEN 990201 AND 990217;
DELETE FROM tasks           WHERE id     BETWEEN 990201 AND 990217;
DELETE FROM spells_new      WHERE id = 42603;
DELETE FROM items           WHERE id = 990001;

